<?php
$currentPage = 'websites';
require_once 'includes/admin_header.php';
require_once '../includes/App.php';
App::boot();
$pdo = App::db();
$tenantService = App::tenantSite();
$csrf = function_exists('csrf_token') ? csrf_token() : ($_SESSION['csrf_token'] ?? '');
$statusFilter = trim((string)($_GET['status'] ?? ''));
$roleFilter = trim((string)($_GET['role'] ?? ''));
$search = trim((string)($_GET['search'] ?? ''));

$where = [];
$params = [];
if ($statusFilter !== '') { $where[] = 'ts.lifecycle_status = ?'; $params[] = $statusFilter; }
if ($roleFilter !== '') { $where[] = 'ts.tenant_type = ?'; $params[] = $roleFilter; }
if ($search !== '') { $where[] = '(ts.site_title LIKE ? OR ts.slug LIKE ? OR u.name LIKE ? OR u.phone LIKE ?)'; array_push($params, "%$search%", "%$search%", "%$search%", "%$search%"); }
$sql = "SELECT ts.*, u.name AS owner_name, u.phone AS owner_phone FROM tenant_sites ts LEFT JOIN users u ON ((ts.tenant_type = 'organization' AND u.id = (SELECT user_id FROM organizations WHERE id = ts.tenant_id LIMIT 1)) OR (ts.tenant_type <> 'organization' AND u.id = ts.tenant_id))";
if ($where) $sql .= ' WHERE ' . implode(' AND ', $where);
$sql .= ' ORDER BY ts.updated_at DESC';
$stmt = $pdo->prepare($sql); $stmt->execute($params); $sites = $stmt->fetchAll(PDO::FETCH_ASSOC);
$orders = $pdo->query("SELECT * FROM website_orders ORDER BY created_at DESC LIMIT 25")->fetchAll(PDO::FETCH_ASSOC);
$tenantOptions = [];
foreach (['doctor', 'pharmacist', 'seller'] as $role) {
    $q = $pdo->prepare("SELECT id, name, phone FROM users WHERE role = ? ORDER BY name"); $q->execute([$role]);
    foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $row) $tenantOptions[] = ['type' => $role, 'id' => $row['id'], 'label' => $row['name'] . ' - ' . $role];
}
$q = $pdo->query("SELECT id, name, phone FROM organizations WHERE status <> 'suspended' ORDER BY name");
foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $row) $tenantOptions[] = ['type' => 'organization', 'id' => $row['id'], 'label' => $row['name'] . ' - organization'];
?>
