    <section class="bg-white rounded-2xl border overflow-hidden"><div class="p-4 border-b"><h2 class="font-black text-lg">وب‌سایت‌های فعال و پیش‌نویس</h2></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-right">سایت</th><th class="p-3 text-right">مالک</th><th class="p-3 text-right">نقش / تیِر</th><th class="p-3 text-right">وضعیت</th><th class="p-3 text-right">عملیات</th></tr></thead><tbody><?php foreach ($sites as $site): ?><tr class="border-t"><td class="p-3"><strong><?= htmlspecialchars($site['site_title']) ?></strong><div class="text-xs text-slate-500 font-mono" dir="ltr"><?= htmlspecialchars($site['slug']) ?>.asena.company</div></td><td class="p-3"><?= htmlspecialchars($site['owner_name'] ?: '—') ?><div class="text-xs text-slate-500"><?= htmlspecialchars($site['owner_phone'] ?: '') ?></div></td><td class="p-3"><?= htmlspecialchars($site['tenant_type']) ?><div class="text-xs text-slate-500"><?= htmlspecialchars($site['site_tier'] ?? 'enterprise') ?></div></td><td class="p-3"><span class="px-2 py-1 rounded-full text-xs font-bold bg-slate-100"><?= htmlspecialchars($site['lifecycle_status'] ?? 'published') ?></span></td><td class="p-3"><div class="flex flex-wrap gap-2"><a class="min-h-10 px-3 rounded-lg bg-slate-100 inline-flex items-center" target="_blank" href="../site.php?slug=<?= urlencode($site['slug']) ?>">پیش‌نمایش</a><a class="min-h-10 px-3 rounded-lg bg-primary text-white inline-flex items-center" href="../<?= htmlspecialchars($site['tenant_type']) ?>/site_builder.php">ویرایش</a><form method="post" action="../actions/admin_websites_action.php" onsubmit="return submitAdminWebsite(this)"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="update_site"><input type="hidden" name="site_id" value="<?= (int)$site['id'] ?>"><input type="hidden" name="lifecycle_status" value="<?= ($site['lifecycle_status'] ?? '') === 'published' ? 'suspended' : 'published' ?>"><input type="hidden" name="site_tier" value="<?= htmlspecialchars($site['site_tier'] ?? 'standard') ?>"><button class="min-h-10 px-3 rounded-lg bg-orange-100 text-orange-800"><?= ($site['lifecycle_status'] ?? '') === 'published' ? 'تعلیق' : 'انتشار' ?></button></form></div></td></tr><?php endforeach; if (!$sites): ?><tr><td colspan="5" class="p-8 text-center text-slate-500">هنوز وب‌سایتی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
    <section class="bg-white rounded-2xl border overflow-hidden"><div class="p-4 border-b"><h2 class="font-black text-lg">درخواست‌های راه‌اندازی</h2></div><div class="divide-y"><?php foreach ($orders as $order): ?><div class="p-4 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><strong><?= htmlspecialchars($order['full_name']) ?></strong><span class="text-xs text-slate-500 mr-2"><?= htmlspecialchars($order['archetype']) ?> / <?= htmlspecialchars($order['tier']) ?></span><div class="text-xs text-slate-500" dir="ltr"><?= htmlspecialchars($order['phone']) ?> · <?= htmlspecialchars($order['desired_slug']) ?>.asena.company</div></div><form method="post" action="../actions/admin_websites_action.php" onsubmit="return submitAdminWebsite(this)" class="flex gap-2"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="update_order"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><select name="status" class="min-h-10 rounded-lg border px-2"><?php foreach (['pending','needs_information','approved','provisioned','in_progress','published','rejected','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $order['status'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><button class="min-h-10 px-3 rounded-lg bg-slate-900 text-white">ذخیره</button></form></div><?php endforeach; if (!$orders): ?><div class="p-8 text-center text-slate-500">درخواستی وجود ندارد.</div><?php endif; ?></div></section>
