"><select name="lifecycle_status" class="w-full min-h-12 rounded-xl border px-3"><option value="draft">پیش‌نویس</option><option value="published">انتشار فوری</option></select><button class="w-full min-h-12 rounded-xl bg-primary text-white font-bold">ایجاد و ثبت بدون پرداخت</button></form></div>
<script>async function submitAdminWebsite(form){event.preventDefault();const r=await fetch(form.action,{method:'POST',body:new FormData(form)});const d=await r.json();if(d.success){location.reload();}else{alert(d.message||'خطا');}return false;}</script>
